using System.Security.Cryptography;
using System.Text.Json.Nodes;

namespace AegiNext.Koumori.Tests;

internal sealed class KoumoriGenerationSnapTestPackage : IDisposable
{
    private readonly KoumoriV2TestPackage package = new();

    internal KoumoriGenerationSnapTestPackage()
    {
        Manifest["schemaVersion"] = 3;
        Manifest["architecture"] = "whisper-small-generation-snap-v1";
        Manifest["modelId"] = "generation-snap-fixture";
        Manifest["training"] = new JsonObject
        {
            ["trained"] = false,
            ["purpose"] = "fixture_only",
            ["qualityAcceptance"] = new JsonObject { ["status"] = "not_met" }
        };
        SetPayload("model", "model.onnx", Convert.FromBase64String(GENERATION));
        SetPayload("encoder", "encoder.onnx", Convert.FromBase64String(ENCODER));
        SetPayload("snapModel", "snap-model.onnx", Convert.FromBase64String(SNAP));
    }

    internal string DirectoryPath => package.DirectoryPath;
    internal JsonObject Manifest => package.Manifest;
    internal static byte[] NonFiniteHead => Convert.FromBase64String(INVALID);

    internal static byte[] InvalidSnapGraph(string defect)
    {
        return Convert.FromBase64String(defect switch
        {
            "shape" => SHAPE,
            "type" => TYPE,
            "context-type" => CONTEXT_TYPE,
            "output-name" => OUTPUT_NAME,
            _ => throw new ArgumentOutOfRangeException(nameof(defect))
        });
    }



    internal void SaveManifest()
    {
        package.SaveManifest();
    }

    internal void SetPayload(string prefix, string filename, byte[] bytes)
    {
        File.WriteAllBytes(Path.Combine(DirectoryPath, filename), bytes);
        Manifest[prefix + "File"] = filename;
        Manifest[prefix + "Sha256"] = Convert.ToHexStringLower(SHA256.HashData(bytes));
        SaveManifest();
    }

    internal void UseGenerationOnly()
    {
        Manifest["schemaVersion"] = 2;
        Manifest["architecture"] = "whisper-small-local-fusion-v1";
        Manifest.Remove("snapModelFile");
        Manifest.Remove("snapModelSha256");
        File.Delete(Path.Combine(DirectoryPath, "snap-model.onnx"));
        SaveManifest();
    }

    internal void UseLegacyGenerationOnly()
    {
        UseGenerationOnly();
        Manifest["schemaVersion"] = 1;
        foreach (var key in Manifest.Select(item => item.Key).Where(key => key.StartsWith("encoder", StringComparison.Ordinal)
                     || key is "architecture" or "contextInputName").ToArray())
        {
            Manifest.Remove(key);
        }
        SetPayload("model", "model.onnx", Convert.FromBase64String(LEGACY_GENERATION));
    }

    /// <inheritdoc />
    public void Dispose()
    {
        package.Dispose();
    }

    private const string LEGACY_GENERATION = "";
    private const string GENERATION = "";
    private const string SNAP = "";
    private const string ENCODER = "CAo6pgEKOAoFc2hhcGUSBmhpZGRlbiIPQ29uc3RhbnRPZlNoYXBlKhYKBXZhbHVlKgoIARABSgQAAAAAoAEEEgdlbmNvZGVyKiUIAxAHQgVzaGFwZUoYAQAAAAAAAADcBQAAAAAAAAADAAAAAAAAWhoKA21lbBITChEIARINCgIIAQoCCFAKAwi4F2IeCgZoaWRkZW4SFAoSCAESDgoCCAEKAwjcCwoDCIAGQgQKABAS";
    private const string INVALID = "";
    private const string SHAPE = "";
    private const string TYPE = "";
    private const string CONTEXT_TYPE = "";
    private const string OUTPUT_NAME = "";
}

